async function addAsset(id,trackId,start){needProject();const a=state.assets.find(a=>a.id===id);if(!a)throw Error('Media no longer exists.');const kind=a.kind==='audio'?'audio':'video';let track=seq().tracks.find(t=>t.id===trackId)||seq().tracks.find(t=>t.kind===kind&&t.enabled&&!t.locked);const ops=[];if(!track){track=trackObject(kind);ops.push(operation('track.add',{sequenceId:seq().id,track}));}if(track.locked)throw Error('Unlock the destination track first.');if(track.kind!==kind)throw Error('Drop this media on a '+kind+' track.');const d=a.kind==='image'?await mediaDuration(a):Math.max(1/fps(),Math.floor((await mediaDuration(a))*fps()+1e-7)/fps()),clip=clipObject(a,start===undefined?trackEnd(track):snap(start),0,d);ops.push(operation('item.add',{sequenceId:seq().id,trackId:track.id,item:clip}));await commit(ops);state.selectedId=clip.id;state.selectedTrack=track.id;state.sourceMode=false;seek(seconds(clip.timelineRange.start));renderTimeline();fillProperties();}
function renderTimeline(){const s=seq();const width=Math.max($('timeline-scroll').clientWidth-100,Math.max(30,duration()+10)*state.zoom);$('timeline-content').style.width=(width+100)+'px';$('ruler').style.width=width+'px';$('ruler').replaceChildren();const step=rulerStep(state.zoom);for(let t=0;t*state.zoom<=width;t+=step){const tick=document.createElement('span');tick.className='tick';tick.style.left=t*state.zoom+'px';tick.textContent=clock(t);$('ruler').append(tick);}for(const marker of s?.markers||[]){const m=document.createElement('span');m.className='marker';m.textContent='◆';m.title=marker.name;m.style.left=seconds(marker.range.start)*state.zoom+'px';$('ruler').append(m);}
 $('tracks').innerHTML=(s?.tracks||[]).slice().sort((a,b)=>b.order-a.order).map(t=>'<div class="track '+(!t.enabled?'disabled':'')+'"><div class="track-label"><b>'+escape(t.name)+'</b><div><button data-lock="'+t.id+'" title="'+(t.locked?'Unlock':'Lock')+' track">'+(t.locked?'🔒':'○')+'</button><button data-mute="'+t.id+'" title="'+(t.muted?'Unmute':'Mute')+' track">'+(t.muted?'M':'♫')+'</button><button data-enable="'+t.id+'" title="Enable / disable track">'+(t.enabled?'●':'◌')+'</button></div></div><div class="lane" data-track="'+t.id+'">'+t.items.map(i=>'<div role="button" tabindex="0" aria-label="'+escape(i.name)+'" class="timeline-clip '+(t.kind==='audio'?'audio':i.type)+' '+(state.selectedId===i.id?'selected':'')+'" data-item="'+i.id+'"><b>'+escape(i.name)+'</b><small>'+clock(seconds(i.timelineRange.duration))+'</small>'+(i.type==='clip'?'<span class="trim left" data-trim="left" title="Trim start"></span><span class="trim right" data-trim="right" title="Trim end"></span>':'')+'</div>').join('')+'</div></div>').join('');
 document.querySelectorAll('[data-item]').forEach(node=>{const t=s.tracks.find(t=>t.id===node.closest('[data-track]').dataset.track);const i=t.items.find(i=>i.id===node.dataset.item);node.style.left=seconds(i.timelineRange.start)*state.zoom+'px';node.style.width=seconds(i.timelineRange.duration)*state.zoom+'px';});$('revision').textContent=state.project?'Revision '+state.project.revision:'No project';if(s)$('format').textContent=s.format.width+' × '+s.format.height;updateHead();}
function fillProperties(){const x=selection();$('selection-name').textContent=x?.item.name||'No clip selected';$('clip-properties').disabled=!x||x.item.type!=='clip'||x.track.locked;if(!x||x.item.type!=='clip')return;const i=x.item;$('clip-start').value=seconds(i.timelineRange.start).toFixed(6);$('source-in').value=seconds(i.sourceRange.start).toFixed(6);$('clip-duration').value=seconds(i.timelineRange.duration).toFixed(6);$('scale').value=i.transform.scaleX??1;$('rotation').value=i.transform.rotation||0;$('opacity').value=i.transform.opacity??1;$('gain').value=i.audio.gainDb||0;}
function selectItem(id){state.selectedId=id;state.selectedTrack=selection()?.track.id;state.sourceMode=false;document.querySelectorAll('[data-item]').forEach(n=>n.classList.toggle('selected',n.dataset.item===id));fillProperties();showInspector(false);}
async function split(){const {track,item}=needClip(),at=snap(state.playhead);if(at<=seconds(item.timelineRange.start)||at>=end(item))throw Error('Click the ruler inside the selected clip, then Split.');pause();await commit([operation('clip.split',{sequenceId:seq().id,trackId:track.id,at:time(at),rightClipId:uid()},item.id)]);}
async function trimTo(item,track,start,source,d){if(item.timeMap.length)throw Error('Use the advanced workbench to trim retimed clips.');const asset=state.assets.find(a=>a.id===item.assetId);const max=await mediaDuration(asset);if(source<0||d<1/fps()||source+d>max+1/fps())throw Error('The trim must stay within the source media.');await commit([operation('clip.trim',{sequenceId:seq().id,trackId:track.id,sourceRange:assetRange(asset,source,d)},item.id),operation('clip.move',{sequenceId:seq().id,fromTrackId:track.id,toTrackId:track.id,timelineStart:time(start)},item.id)]);}
let pointer=null;
$('ruler').addEventListener('pointerdown',event=>{if(state.running||event.button!==0)return;const rect=$('ruler').getBoundingClientRect();pointer={mode:'seek',left:rect.left};$('ruler').setPointerCapture(event.pointerId);seek((event.clientX-rect.left)/state.zoom);});
$('tracks').addEventListener('pointerdown',event=>{if(state.running||state.busy||event.button!==0||event.target.closest('button'))return;const node=event.target.closest('[data-item]'),lane=event.target.closest('[data-track]');if(!lane)return;if(!node){pointer={mode:'seek',left:lane.getBoundingClientRect().left};seek((event.clientX-pointer.left)/state.zoom);return;}selectItem(node.dataset.item);const {item,track}=selection();if(track.locked||item.locked||item.type!=='clip')return;pause();event.preventDefault();pointer={mode:event.target.dataset.trim||'move',node,item,track,x:event.clientX,start:seconds(item.timelineRange.start),source:seconds(item.sourceRange.start),duration:seconds(item.sourceRange.duration),moved:false};node.setPointerCapture(event.pointerId);});
document.addEventListener('pointermove',event=>{if(!pointer)return;if(pointer.mode==='seek'){seek((event.clientX-pointer.left)/state.zoom);return;}const p=pointer,delta=(event.clientX-p.x)/state.zoom;p.moved=p.moved||Math.abs(event.clientX-p.x)>3;if(p.mode==='move')p.node.style.left=snap(p.start+delta)*state.zoom+'px';else if(p.mode==='right')p.node.style.width=Math.max(1/fps(),p.duration+delta)*state.zoom+'px';else{const d=Math.max(-p.source,-p.start,Math.min(p.duration-1/fps(),delta));p.node.style.left=(p.start+d)*state.zoom+'px';p.node.style.width=(p.duration-d)*state.zoom+'px';}});
document.addEventListener('pointerup',guard(async event=>{const p=pointer;pointer=null;if(!p||p.mode==='seek'||!p.moved)return;const delta=(event.clientX-p.x)/state.zoom;try{if(p.mode==='move'){const lane=document.elementFromPoint(event.clientX,event.clientY)?.closest('[data-track]');await commit([operation('clip.move',{sequenceId:seq().id,fromTrackId:p.track.id,toTrackId:lane?.dataset.track||p.track.id,timelineStart:time(snap(p.start+delta))},p.item.id)]);}else if(p.mode==='right')await trimTo(p.item,p.track,p.start,p.source,snap(Math.max(1/fps(),p.duration+delta)));else{const d=snap(p.source+Math.max(-p.source,-p.start,Math.min(p.duration-1/fps(),delta)))-p.source;await trimTo(p.item,p.track,p.start+d,p.source+d,p.duration-d);}}finally{renderTimeline();}}));
document.addEventListener('pointercancel',()=>{pointer=null;renderTimeline();});
$('tracks').addEventListener('dragover',event=>{const lane=event.target.closest('[data-track]');if(lane){event.preventDefault();lane.classList.add('drag-over');}});
$('tracks').addEventListener('dragleave',event=>event.target.closest('[data-track]')?.classList.remove('drag-over'));
$('tracks').addEventListener('drop',guard(async event=>{event.preventDefault();const lane=event.target.closest('[data-track]');if(!lane)return;lane.classList.remove('drag-over');await addAsset(event.dataTransfer.getData('application/frameos-asset'),lane.dataset.track,(event.clientX-lane.getBoundingClientRect().left)/state.zoom);}));
$('tracks').addEventListener('click',guard(async event=>{const b=event.target.closest('button');if(!b)return;const id=b.dataset.lock||b.dataset.mute||b.dataset.enable,t=seq().tracks.find(t=>t.id===id);if(!t)return;const type=b.dataset.lock?(t.locked?'track.unlock':'track.lock'):b.dataset.mute?(t.muted?'track.unmute':'track.mute'):'track.update';await commit([operation(type,{sequenceId:seq().id,...(b.dataset.enable?{values:{enabled:!t.enabled}}:{})},id)]);}));
$('media-list').addEventListener('click',guard(async event=>{if(event.target.closest('input'))return;const add=event.target.closest('[data-add]');if(add){await addAsset(add.dataset.add);return;}const card=event.target.closest('[data-asset]');if(card)await selectMedia(card.dataset.asset);}));
$('media-list').addEventListener('change',event=>{const id=event.target.dataset.check;if(id){event.target.checked?state.checked.add(id):state.checked.delete(id);invalidateBriefCheck();}});
$('media-list').addEventListener('dblclick',guard(async event=>{if(event.target.closest('button,input'))return;const card=event.target.closest('[data-asset]');if(card)await addAsset(card.dataset.asset);}));
$('media-list').addEventListener('dragstart',event=>{const card=event.target.closest('[data-asset]');if(card){event.dataTransfer.setData('application/frameos-asset',card.dataset.asset);event.dataTransfer.effectAllowed='copy';}});
$('media-list').addEventListener('keydown',guard(async event=>{if(event.key==='Enter'&&event.target.dataset.asset)await selectMedia(event.target.dataset.asset);}));
$('tracks').addEventListener('keydown',event=>{if(event.key==='Enter'&&event.target.dataset.item)selectItem(event.target.dataset.item);});
async function importFiles(){needProject();if(state.running||state.busy)throw Error('Wait for the current edit to finish.');pause();state.busy=true;let imported=0,lastAsset=null;const failures=[];try{const files=Array.from($('files').files);for(const [index,file] of files.entries()){$('save-state').textContent='Importing '+(index+1)+'/'+files.length+': '+file.name;try{const form=new FormData();form.append('file',file);const kind=file.type.startsWith('audio/')?'audio':file.type.startsWith('image/')?'image':'video';const r=await fetch('/api/v1/assets/uploads?projectId='+state.project.projectId+'&baseRevision='+state.project.revision+'&kind='+kind,{method:'POST',headers:state.token?{authorization:'Bearer '+state.token}:{},body:form});const e=await r.json();if(!r.ok||e.error)throw Error(e.error?.message||'Import failed.');if(e.data.transaction?.project)applyProjectSnapshot(e.data.transaction.project);else applyProjectSnapshot(await api('GET','/projects/'+state.project.projectId));state.checked.add(e.data.asset.id);lastAsset=e.data.asset;imported++;}catch(error){failures.push(file.name+': '+error.message);}}if(lastAsset){state.selectedAsset=lastAsset.id;state.sourceMode=true;state.sourceTime=0;renderMedia();await mediaDuration(lastAsset).then(showFrame).then(()=>thumbnail(lastAsset)).catch(error=>failures.push('Files imported; preview: '+error.message));renderMedia();updateHead();}toast(imported+' file(s) imported.'+(failures.length?' '+failures.join('; '):' Drag clips to the timeline to edit.'),failures.length>0);}finally{state.busy=false;$('files').value='';$('save-state').textContent=failures.length?'Import completed with errors':'Saved';}}

function renderReference(){const select=$('reference-video');select.replaceChildren(new Option('No reference',''));for(const asset of state.assets.filter(a=>a.kind==='video'))select.add(new Option(asset.name,asset.id));select.value=state.referenceAssetId||'';if(!select.value)state.referenceAssetId=null;}
$('reference-video').addEventListener('change',()=>{if(state.running||state.busy){renderReference();return;}state.referenceAssetId=$('reference-video').value||null;state.checked.delete(state.referenceAssetId);state.plan=null;invalidateBriefCheck();$('approve').hidden=true;renderMedia();});
bind('import-reference',()=>{needProject();if(state.running||state.busy)throw Error('Wait for the current operation.');$('reference-file').click();});
$('reference-file').addEventListener('change',guard(async()=>{needProject();if(state.running||state.busy)throw Error('Wait for the current operation.');const file=$('reference-file').files[0];if(!file)return;state.busy=true;try{const form=new FormData();form.append('file',file);const response=await fetch('/api/v1/assets/uploads?projectId='+state.project.projectId+'&baseRevision='+state.project.revision+'&kind=video',{method:'POST',headers:state.token?{authorization:'Bearer '+state.token}:{},body:form});const result=await response.json();if(!response.ok||result.error)throw Error(result.error?.message||'Reference import failed.');state.referenceAssetId=result.data.asset.id;await reload();state.checked.delete(state.referenceAssetId);renderMedia();toast('Reference imported. Select source clips and describe your edit.');}finally{state.busy=false;$('reference-file').value='';}}));
async function refreshJobs(){if(!state.project)return;const jobs=await api('GET','/jobs?projectId='+state.project.projectId);$('jobs').innerHTML=jobs.slice(0,15).map(j=>'<article class="job '+escape(j.status)+'"><b>'+escape(j.kind)+' · '+escape(j.status)+'</b><br><small>'+Math.round((j.progress||0)*100)+'% '+escape(j.error?.message||'')+'</small>'+((j.output?.artifacts||[]).filter(a=>a.mimeType==='video/mp4').map(a=>'<button class="wide" data-download-job="'+j.id+'" data-download-name="'+escape(a.name)+'">Download video</button>').join(''))+'</article>').join('')||'<p class="hint">No jobs yet.</p>';}
$('jobs').addEventListener('click',guard(async event=>{const b=event.target.closest('[data-download-job]');if(!b)return;const projectId=await ensurePlaybackSession();const a=document.createElement('a');a.href='/api/v1/projects/'+projectId+'/jobs/'+b.dataset.downloadJob+'/artifacts/'+encodeURIComponent(b.dataset.downloadName);a.download=b.dataset.downloadName;document.body.append(a);a.click();a.remove();}));
async function analyze(asset,purpose='source'){return api('POST','/projects/'+state.project.projectId+'/assets/'+asset.id+'/analysis',{projectId:state.project.projectId,assetId:asset.id,analyzers:['google.vertex.gemini.video'],parameters:{'google.vertex.gemini.video':{purpose}}});}
async function searchAsset(asset,query=''){return api('POST','/assets/search',{projectId:state.project.projectId,assetIds:[asset.id],query,types:['visual_semantic','scenes','shots','quality'],mode:'lexical',limit:500});}
function log(message){const li=document.createElement('li');li.textContent=message;$('agent-log').append(li);}
async function waitForAnalysis(job){let current=job;for(let i=0;i<600;i++){if(state.stop){await api('DELETE','/jobs/'+job.id).catch(()=>{});throw Error('Stopped. No montage edits were applied.');}if(current.status==='completed')return;if(['failed','cancelled'].includes(current.status))throw Error(current.error?.message||'Video analysis failed.');await new Promise(r=>setTimeout(r,1500));current=await api('GET','/jobs/'+job.id);}throw Error('Analysis is still running. Check Activity and propose again when it finishes.');}
async function proposeMontage(){
 needProject();if(state.running||state.busy)throw Error('Wait for the current operation.');
 if(!state.briefCheck?.accepted||!state.briefCheck.result.ready||state.briefCheck.signature!==briefSignature())throw Error('Check and accept the editing brief before analyzing footage.');
 if($('planner-mode').value==='advanced'){state.capabilities=await api('GET','/capabilities');if(!state.capabilities.some(c=>c.id==='engine.mlt'&&c.available))throw Error('Advanced planning needs a configured native renderer. Choose Simple editing or configure the renderer first.');}
 const brief=$('brief').value.trim();if(!brief)throw Error('Describe how you want the video edited.');
 const referenceAssetId=$('reference-video').value||undefined;const reference=state.assets.find(a=>a.id===referenceAssetId);const assets=state.assets.filter(a=>state.checked.has(a.id)&&a.id!==referenceAssetId);if(reference&&assets.some(a=>a.kind!=='video'))throw Error('Select video source clips for reference editing.');if(referenceAssetId&&(!reference||!assets.length))throw Error('Choose a reference and separate source clips.');if(assets.length>20)throw Error('Select up to 20 media files.');
 state.running=true;state.stop=false;state.plan=null;$('approve').hidden=true;$('stop').hidden=false;$('propose').disabled=true;$('agent-log').replaceChildren();$('plan').textContent='Preparing your AI editing request…';
 try{
 const durations={};const used=new Set([...assets.map(a=>a.id),...seq().tracks.flatMap(t=>t.items.filter(i=>i.type==='clip').map(i=>i.assetId))]);
 for(const id of used){if(state.stop)throw Error('Stopped. No timeline edits were applied.');const asset=state.assets.find(a=>a.id===id);durations[id]=await mediaDuration(asset);}
 if(reference){log('Analyzing reference editing style…');await waitForAnalysis(await analyze(reference,'reference'));}if(reference||$('analyze-before-plan').checked){const videos=assets.length?assets:state.assets.filter(a=>used.has(a.id));for(const asset of videos.filter(a=>a.kind==='video')){if(state.stop)throw Error('Stopped. No edits were applied.');let results=await searchAsset(asset);if(reference||!results.some(r=>r.range)){log('Analyzing '+asset.name+' with Gemini…');await waitForAnalysis(await analyze(asset));}}}
 if(state.stop)throw Error('Stopped. No edits were applied.');
 log('Gemini is interpreting your editing brief…');
 await reload();const revision=state.project.revision;
 const proposal=await api('POST','/studio/ai/plan',{planner:$('planner-mode').value,projectId:state.project.projectId,baseRevision:revision,brief,referenceAssetId,assetIds:assets.map(a=>a.id),selectedItemId:state.selectedId,playhead:state.playhead,durations,secondsPerClip:Number($('montage-length').value)});
 if(proposal.planning){log('Planning stages: '+proposal.planning.stages.join(' → '));for(const tool of proposal.planning.selection?.tools||[])log(tool.name+': '+tool.purpose);}
 if(state.stop)throw Error('Stopped. The returned plan was discarded; no edits were applied.');
 if(proposal.reference)log('Reference style analyzed: '+proposal.reference.analyzedShots+' shots. Review the proposed match below.');if(proposal.clarification){$('plan').textContent=proposal.clarification;log('AI needs clarification. Update your brief and try again.');return;}
 state.plan={...proposal,requestContext:{brief,assetIds:assets.map(a=>a.id),referenceAssetId,durations,secondsPerClip:Number($('montage-length').value)},reviewCount:0,visualEnabled:$('visual-checkpoints').checked,steps:proposal.steps.map(s=>({...s,target:s.assetId?'[data-asset="'+s.assetId+'"]':s.itemId?'[data-item="'+s.itemId+'"]':'#tracks'}))};
 if(proposal.planning){state.plan.visualEnabled=false;proposal.warnings.push('Advanced plans require manual playback review. Automatic correction from still frames is unavailable in this mode.');}
 $('plan').innerHTML='<h2>Review AI edit plan</h2><p>'+escape(proposal.summary)+'</p><p class="hint" id="plan-status">'+escape(proposal.model)+' · '+proposal.steps.length+' actions · no edits applied yet</p>'+proposal.warnings.map(w=>'<p class="hint">'+escape(w)+'</p>').join('')+proposal.steps.map((s,i)=>'<article><b>'+(i+1)+'. '+escape(s.label)+'</b><small>'+escape(s.op.type)+'</small><details><summary>Exact edit parameters</summary><pre>'+escape(JSON.stringify(s.op.arguments,null,2))+'</pre></details></article>').join('');
 $('approve').hidden=!proposal.steps.length;log('AI plan validated. Review and approve to watch it execute.');
 }catch(e){state.plan=null;$('plan').textContent=e.message;throw e;}
 finally{state.running=false;$('stop').hidden=true;invalidateBriefCheck();}
}

async function decodedFrame(media){
 if(media.readyState>=2&&!media.seeking)return;
 await new Promise((resolve,reject)=>{const done=()=>{if(media.readyState>=2&&!media.seeking){cleanup();resolve();}},fail=()=>{cleanup();reject(Error('Preview frame could not be decoded.'));},cleanup=()=>{clearTimeout(timer);for(const event of ['seeked','loadeddata','canplay'])media.removeEventListener(event,done);media.removeEventListener('error',fail);};const timer=setTimeout(fail,12000);for(const event of ['seeked','loadeddata','canplay'])media.addEventListener(event,done);media.addEventListener('error',fail);done();});
}
function drawPreviewLayer(context,media,opacity=1){
 const width=media.videoWidth||media.naturalWidth,height=media.videoHeight||media.naturalHeight;if(!width||!height)return;
 const cw=context.canvas.width,ch=context.canvas.height,fit=Math.min(cw/width,ch/height),style=getComputedStyle(media),matrix=new DOMMatrix(style.transform==='none'?undefined:style.transform);
 context.save();context.translate(cw/2,ch/2);context.transform(matrix.a,matrix.b,matrix.c,matrix.d,0,0);context.globalAlpha=opacity;context.drawImage(media,-width*fit/2,-height*fit/2,width*fit,height*fit);context.restore();
}
async function captureEvidence(referenceAssetId){
 const original={projectId:state.project.projectId,playhead:state.playhead,sourceMode:state.sourceMode,sourceTime:state.sourceTime,selectedAsset:state.selectedAsset};
 const revision=state.project.revision,frames=[],canvas=document.createElement('canvas');canvas.width=640;canvas.height=Math.max(1,Math.round(640*$('preview-stage').clientHeight/Math.max(1,$('preview-stage').clientWidth)));const context=canvas.getContext('2d');
 const emit=(role,at)=>{const jpeg=canvas.toDataURL('image/jpeg',.72).split(',')[1];if(jpeg.length>350000)throw Error('Preview frame exceeds the review size limit.');frames.push({role,at,jpeg});};
 try{
  const total=duration();if(!total)throw Error('There is no timeline footage to visually review yet.');
  const transitions=seq().tracks.filter(t=>t.enabled).flatMap(t=>t.items.filter(i=>i.enabled&&i.type==='transition'));
  const times=[total*.08,total*.3,total*.55,total*.8,total*.96];
  for(const tr of transitions.slice(0,1))times.push(seconds(tr.timelineRange.start)+seconds(tr.timelineRange.duration)*.25,seconds(tr.timelineRange.start)+seconds(tr.timelineRange.duration)*.75);
  for(const at of [...new Set(times.map(t=>Math.max(0,Math.min(total-1/fps(),snap(t)))))].sort((a,b)=>a-b)){
   if(state.stop)throw Error('Visual review stopped. Applied edits remain.');
   state.sourceMode=false;state.playhead=at;await showFrame();
   for(const video of [$('preview'),$('transition-preview')])if(!video.hidden)await decodedFrame(video);
   context.fillStyle='#080809';context.fillRect(0,0,canvas.width,canvas.height);
   for(const media of [$('preview'),$('image-preview'),$('transition-preview')])if(!media.hidden){if(media.tagName==='IMG'&&!media.complete)await media.decode();drawPreviewLayer(context,media,Number(getComputedStyle(media).opacity));}
   const title=$('title-overlay');if(title.textContent){context.fillStyle='#efeff5';const scale=640/Math.max(1,title.clientWidth);context.font='600 '+(30*scale)+'px Segoe UI';context.textAlign='center';context.textBaseline='middle';const lines=title.textContent.split('\n');lines.forEach((line,index)=>context.fillText(line,canvas.width/2,canvas.height/2+(index-(lines.length-1)/2)*36*scale,canvas.width-20));}
   emit('timeline',at);
  }
  if(referenceAssetId){const asset=state.assets.find(a=>a.id===referenceAssetId);if(!asset)throw Error('Reference no longer exists.');const video=document.createElement('video');video.muted=true;video.preload='auto';try{video.src=await mediaUrl(asset);await decodedFrame(video);if(!Number.isFinite(video.duration)||video.duration<=0)throw Error('Reference duration is unavailable.');for(const fraction of [.15,.5,.85]){if(state.stop)throw Error('Visual review stopped.');const at=video.duration*fraction;video.currentTime=at;await decodedFrame(video);context.fillStyle='#080809';context.fillRect(0,0,canvas.width,canvas.height);const fit=Math.min(canvas.width/video.videoWidth,canvas.height/video.videoHeight);context.drawImage(video,(canvas.width-video.videoWidth*fit)/2,(canvas.height-video.videoHeight*fit)/2,video.videoWidth*fit,video.videoHeight*fit);emit('reference',at);}}finally{video.pause();video.removeAttribute('src');video.load();}}
  const latest=await api('GET','/projects/'+original.projectId);if(latest.revision!==revision)throw Error('The timeline changed during capture. Generate a fresh plan.');return {frames,revision};
 }finally{if(state.project?.projectId===original.projectId){Object.assign(state,{playhead:original.playhead,sourceMode:original.sourceMode,sourceTime:original.sourceTime,selectedAsset:original.selectedAsset});await showFrame();updateHead();}}
}
async function visualCheckpoint(plan,completed){
 if(!duration())return null;
 pause();log('Capturing the edited preview for visual review…');$('visual-review').textContent='Capturing timeline and reference frames…';
 let evidence;try{evidence=await captureEvidence(plan.requestContext.referenceAssetId);}catch(error){$('visual-review').textContent='Visual capture interrupted: '+error.message;throw error;}const {frames,revision}=evidence;
 if(state.stop)throw Error('Visual review stopped. Applied edits remain.');
 plan.reviewCount=(plan.reviewCount||0)+1;
 let result;try{result=await api('POST','/studio/ai/review',{...plan.requestContext,projectId:plan.projectId,baseRevision:revision,playhead:state.playhead,frames,pendingEdits:plan.steps.slice(completed).map(s=>s.label)});}catch(error){const message=error?.message||String(error);if(/cannot be safely applied|No edits were applied/i.test(message)){const p=document.createElement('p');p.className='hint';p.textContent='Gemini proposed a correction that failed timeline validation; it was discarded and the approved edits remain.';$('visual-review').replaceChildren(p);log('Visual correction discarded after deterministic validation.');return null;}$('visual-review').textContent='Visual review failed. Applied edits remain; generate a fresh plan to continue. '+message;throw error;}
 if(state.stop)throw Error('Review discarded after Stop. Applied edits remain.');
 const latest=await api('GET','/projects/'+plan.projectId);if(latest.revision!==revision)throw Error('Timeline changed during visual review. Generate a fresh plan.');
 $('visual-review').replaceChildren();const heading=document.createElement('h2');heading.textContent='Visual checkpoint '+plan.reviewCount+' / 3';const text=document.createElement('p');text.textContent=result.summary;const limits=document.createElement('p');limits.className='hint';limits.textContent='Reviewed '+frames.length+' sampled browser frames; continuous motion and sound were not reviewed.';$('visual-review').append(heading,text,limits);
 for(const warning of result.warnings){const p=document.createElement('p');p.className='hint';p.textContent=warning;$('visual-review').append(p);}
 if(result.clarification){const p=document.createElement('p');p.textContent=result.clarification+' Execution is paused. Update your brief and generate a fresh plan to continue.';$('visual-review').append(p);return {...result,steps:[]};}
 if(!result.steps.length){log('Visual checkpoint: no corrections proposed for the sampled frames.');return null;}
 log('Visual review proposed corrections. Execution paused for approval.');
 return {...result,requestContext:plan.requestContext,reviewCount:plan.reviewCount,visualEnabled:plan.visualEnabled,steps:result.steps.map(s=>({...s,target:s.assetId?'[data-asset="'+s.assetId+'"]':s.itemId?'[data-item="'+s.itemId+'"]':'#tracks'}))};
}
function showCorrection(plan){showInspector(true);$('plan').innerHTML='<h2>Review visual corrections</h2><p>'+escape(plan.summary)+'</p><p class="hint" id="plan-status">The remaining plan has been replaced. These edits require approval.</p>'+plan.warnings.map(w=>'<p class="hint">'+escape(w)+'</p>').join('')+plan.steps.map((s,i)=>'<article><b>'+(i+1)+'. '+escape(s.label)+'</b><details><summary>Edit parameters</summary><pre>'+escape(JSON.stringify(s.op.arguments,null,2))+'</pre></details></article>').join('');}

async function approveAdvancedPlan(plan){
 if(state.running||state.busy)return;
 if(state.project.projectId!==plan.projectId)throw Error('Open the project this plan belongs to.');
 pause();state.running=true;state.busy=true;$('approve').hidden=true;$('propose').disabled=true;
 plan.applyKey=plan.applyKey||'studio-advanced-'+uid();
 try{
  if($('plan-status'))$('plan-status').textContent='Applying the approved plan…';
  const result=await api('POST','/transactions',{projectId:plan.projectId,baseRevision:plan.revision,idempotencyKey:plan.applyKey,mode:'commit',operations:plan.steps.map(s=>s.op)});
  applyProjectSnapshot(result.project);state.plan=null;state.sourceMode=false;
  for(const step of plan.steps)log('✓ '+step.label);
  if($('plan-status'))$('plan-status').textContent=plan.steps.length+' edits applied together. One Undo restores the previous timeline.';
  renderTimeline();await showFrame().catch(e=>log('Edits saved. Preview: '+e.message));
  toast('AI edits saved. Export to review native effects, compositing and animated titles.');
 }catch(error){
  state.plan=plan;$('approve').hidden=false;
  if($('plan-status'))$('plan-status').textContent='The transaction was not confirmed. Retry uses the same request and cannot duplicate edits. '+error.message;
  throw error;
 }finally{state.running=false;state.busy=false;$('propose').disabled=true;}
}

async function approvePlan(){const plan=state.plan;if(!plan)throw Error('Create a plan first.');if(plan.planning)return approveAdvancedPlan(plan);if(state.running||state.busy)return;const latest=await api('GET','/projects/'+plan.projectId);if(latest.revision!==plan.revision||state.project.projectId!==plan.projectId){state.plan=null;$('approve').hidden=true;throw Error('The project changed. Generate a fresh plan before approving.');}pause();state.running=true;state.stop=false;$('approve').hidden=true;$('stop').hidden=false;$('propose').disabled=true;document.body.classList.add('agent-running');let completed=0;let correctionPlan=null;let reviewPaused=false;try{showPanel('media');for(const step of plan.steps){if(state.stop)break;const target=document.querySelector(step.target)||$('tracks');target.scrollIntoView({block:'nearest',inline:'nearest'});const rect=target.getBoundingClientRect();const cursor=$('agent-cursor');cursor.hidden=false;cursor.style.left=(rect.left+Math.min(30,rect.width/2))+'px';cursor.style.top=(rect.top+Math.min(20,rect.height/2))+'px';target.classList.add('agent-target');await new Promise(r=>requestAnimationFrame(r));target.classList.remove('agent-target');if(state.stop)break;await commit([step.op],true);completed++;if($('plan-status'))$('plan-status').textContent=completed+' / '+plan.steps.length+' edits applied';if(step.op.arguments.item){state.selectedId=step.op.arguments.item.id;state.sourceMode=false;state.playhead=seconds(step.op.arguments.item.timelineRange.start);renderTimeline();await showFrame();}if(step.itemId){state.selectedId=step.itemId;const chosen=selection();if(chosen){state.sourceMode=false;state.playhead=seconds(chosen.item.timelineRange.start);fillProperties();renderTimeline();await showFrame();}}log('✓ '+step.label);
if(plan.visualEnabled&&plan.requestContext&&!state.stop&&(completed===plan.steps.length||(completed%10===0&&(plan.reviewCount||0)<2))&&(plan.reviewCount||0)<3){
 const outcome=await visualCheckpoint(plan,completed);
 if(outcome){reviewPaused=true;correctionPlan=outcome.steps.length?outcome:null;break;}
}
}toast(reviewPaused?'Visual review paused the edit. Review the feedback and proposed corrections.':state.stop?'Stopped after '+completed+' edits. Applied edits remain; use Undo to reverse them.':'AI edits applied. Press Play to review.');log(reviewPaused?'Visual feedback requires review before continuing.':state.stop?'Stopped. '+completed+' edits applied.':'Finished. Review the AI edit in the player.');}finally{if($('plan-status'))$('plan-status').textContent=(reviewPaused?'Paused for visual review':completed===plan.steps.length?'Completed':state.stop?'Stopped':'Interrupted')+' · '+completed+' / '+plan.steps.length+' edits applied';state.running=false;state.plan=correctionPlan;if(correctionPlan){showCorrection(correctionPlan);$('approve').hidden=false;}$('agent-cursor').hidden=true;$('stop').hidden=true;$('propose').disabled=true;document.body.classList.remove('agent-running');renderTimeline();if(!state.stop)$('fit').click();}}
