window.frameosEditor={propose:async proposal=>{needProject();if(state.running||state.busy)throw Error('Editor is busy.');if(!Array.isArray(proposal.operations)||!proposal.operations.length||proposal.operations.length>200)throw Error('Expected 1–200 operations.');const proposalProject=state.project.projectId,proposalRevision=state.project.revision;const operations=structuredClone(proposal.operations).map(o=>({...o,operationId:uid(),preconditions:o.preconditions||[],provenance:{actorType:'agent',actorId:'studio.connected-agent'}}));await api('POST','/transactions',{projectId:state.project.projectId,baseRevision:state.project.revision,idempotencyKey:'proposal-'+uid(),mode:'validate',operations});if(state.project.projectId!==proposalProject||state.project.revision!==proposalRevision)throw Error('The project changed while validating the proposal.');state.plan={projectId:proposalProject,revision:proposalRevision,steps:operations.map(op=>({label:op.type,target:'#tracks',op}))};showInspector(true);$('plan').replaceChildren();const heading=document.createElement('h2');heading.textContent=proposal.summary||'Connected agent proposal';$('plan').append(heading);for(const op of operations){const details=document.createElement('details');const summary=document.createElement('summary');summary.textContent=op.type;const pre=document.createElement('pre');pre.textContent=JSON.stringify(op.arguments,null,2);details.append(summary,pre);$('plan').append(details);}$('approve').hidden=false;},getState:()=>({projectId:state.project?.projectId,revision:state.project?.revision,playhead:state.playhead,selectedItemId:state.selectedId,running:state.running})};
const plannerLabel=document.createElement('label');plannerLabel.textContent='Planning mode';const plannerSelect=document.createElement('select');plannerSelect.id='planner-mode';for(const [value,text] of [['advanced','Advanced AI editing & effects'],['simple','Simple editing']]){const option=document.createElement('option');option.value=value;option.textContent=text;plannerSelect.append(option);}plannerLabel.append(plannerSelect);$('brief-check').before(plannerLabel);
